function setMode(next){mode=next;const inch=4/state().width;Object.entries(parts).forEach(([name,g])=>{g.position.z=0;g.visible=!hiddenParts.has(name);});if(mode==='exploded'){parts.face.position.z=.9;parts.returns.position.z=.2;parts.leds.position.z=.6;parts.acrylic.position.z=-.55;parts.studs.position.z=-.7;parts.wires.position.z=.4;parts.drain.position.z=.2;parts.driver.position.z=-.7;}if(mode==='internal')parts.face.visible=false;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('modehint').textContent=mode==='exploded'?'Separated layers reveal your metal shell, rear-facing LEDs, acrylic back and wall mounting.':mode==='internal'?'Face removed to inspect the LEDs and wiring. The LEDs point towards the acrylic back.':'Opaque metal face and returns. Light exits through the acrylic back and reflects from the wall.';if(wallMesh){wallMesh.visible=mode==='assembled';haloMesh.visible=mode==='assembled'&&isLit;}}
