async function capture(){if(busy||!art||!renderer)return;busy=true;$('capture').disabled=true;const old={pos:camera.position.clone(),target:orbit.target.clone(),mode,lit:isLit,rotate:$('rotate').checked};$('rotate').checked=false;shots=[];setMode('assembled');try{for(const lit of [true,false]){setLighting(lit);for(const name of Object.keys(views)){view(name);renderOnce();shots.push({name,lit,url:imagePNG()});await new Promise(r=>requestAnimationFrame(r));}}$('gallery').hidden=false;$('shots').replaceChildren();for(const shot of shots){const el=document.createElement('div');el.className='shot';const im=document.createElement('img');im.src=shot.url;im.alt=shot.name+' · '+(shot.lit?'lit':'unlit');const row=document.createElement('div'),title=document.createElement('span');title.textContent=shot.name+' / '+(shot.lit?'Lit':'Unlit');const a=document.createElement('a');a.href=shot.url;a.download='halo-'+shot.name+'-'+(shot.lit?'lit':'unlit')+'.png';a.textContent='↓ PNG';row.append(title,a);el.append(im,row);$('shots').append(el);}toast('12 views captured. Download any view or the full sheet.');}catch(e){toast('Capture failed: '+e.message);}finally{setLighting(old.lit);setMode(old.mode);camera.position.copy(old.pos);orbit.target.copy(old.target);$('rotate').checked=old.rotate;orbit.update();busy=false;$('capture').disabled=false;}}
