function update(){const s=state();if(!Number.isFinite(s.cct)||s.cct<1800||s.cct>12000){toast('White temperature must be 1800–12000K.');return;}if(!Number.isFinite(s.width)||s.width<4||s.width>240||!Number.isFinite(s.depth)||s.depth<.5||s.depth>8||!Number.isFinite(s.gap)||s.gap<.25||s.gap>6){toast('Width: 4–240″; depth: 0.5–8″; wall gap: 0.25–6″.');return;}$('depthfield').hidden=!$('customdepth').checked;$('paintfield').hidden=s.finish!=='custom';$('rgbfield').hidden=s.led!=='rgb';$('cctfield').hidden=s.led!=='cct';invalidate();build();}
async function upload(file){if(!file)return;if(file.size>15*1024*1024){toast('Please use an image smaller than 15 MB.');return;}if(!/\.(png|jpe?g|webp|svg)$/i.test(file.name)){toast('Please upload PNG, JPG, WebP or SVG artwork.');return;}const r=new FileReader();r.onload=async()=>{try{await readImage(r.result,file.name);invalidate();toast('Artwork loaded.');}catch(e){toast(e.message);}};r.onerror=()=>toast('Could not read the file.');r.readAsDataURL(file);}
$('file').addEventListener('change',e=>upload(e.target.files[0]));$('drop').addEventListener('dragover',e=>{e.preventDefault();$('drop').classList.add('drag');});$('drop').addEventListener('dragleave',()=>$('drop').classList.remove('drag'));$('drop').addEventListener('drop',e=>{e.preventDefault();$('drop').classList.remove('drag');upload(e.dataTransfer.files[0]);});$('sample').onclick=()=>{invalidate();readImage('sample.png','West · sample artwork').catch(e=>toast(e.message));};$('background').onchange=()=>{invalidate();processArt();};
for(const id of ['width','gap','depth','customdepth','finish','paint','led','cct','rgb','intensity','wall'])$(id).addEventListener('change',update);
$('intensity').addEventListener('input',()=>{$('intensityout').textContent=$('intensity').value+'%';if(haloMesh)haloMesh.material.opacity=isLit?+$('intensity').value/100*1.7:0;});
$('lit').onclick=()=>setLighting(true);$('unlit').onclick=()=>setLighting(false);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const p=b.dataset.part;hiddenParts.has(p)?hiddenParts.delete(p):hiddenParts.add(p);b.classList.toggle('off',hiddenParts.has(p));setMode(mode);});$('resetview').onclick=()=>view('right');$('export').onclick=exportPNG;$('capture').onclick=capture;$('sheet').onclick=contactSheet;$('reference').onclick=()=>$('refdialog').showModal();$('closemodal').onclick=()=>$('refdialog').close();
$('saveproject').onclick=()=>{if(!art)return;const json=JSON.stringify({version:1,settings:state(),background:$('background').value,customDepth:$('customdepth').checked,artwork:art.src,name:art.name},null,2),url=URL.createObjectURL(new Blob([json],{type:'application/json'}));download(url,'halo-studio-project.json');setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Project saved with artwork and settings.');};
$('loadproject').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw new Error('Project file is too large.');const p=JSON.parse(await file.text());if(p.version!==1||!p.settings||typeof p.artwork!=='string'||!(/^(data:image\/(png|jpeg|webp|svg\+xml);base64,|sample\.png$)/.test(p.artwork)))throw new Error('Invalid project file.');const s=p.settings;if(![s.width,s.gap,s.depth,s.intensity].every(Number.isFinite)||s.width<4||s.width>240||s.depth<.5||s.depth>8||s.gap<.25||s.gap>6||s.intensity<0||s.intensity>1)throw new Error('Invalid project dimensions.');for(const id of ['width','gap','depth','finish','paint','led','cct','rgb','wall']){if(typeof s[id]!=='string'&&typeof s[id]!=='number')throw new Error('Invalid project settings.');$(id).value=s[id];}$('intensity').value=s.intensity*100;$('customdepth').checked=!!p.customDepth;$('background').value=p.background||'auto';await readImage(p.artwork,p.name||'Artwork');update();toast('Project restored.');}catch(err){toast(err.message);}};
if(init())readImage('sample.png','West · sample artwork').catch(e=>toast(e.message));
